// Full-screen cards and a tap-built storyboard. No typed command language required.
function openCardScreen(){document.body.classList.add('fullscreen-card','lesson-mode');hub.insertAdjacentHTML('afterbegin','<div class="card-screen-chrome"><span class="pull-handle" aria-hidden="true"></span><button data-close-card aria-label="Close card and return home">×</button></div>')}
const immersiveFocus=focusStep;focusStep=function(){immersiveFocus();openCardScreen()};
const immersiveLift=liftSession;liftSession=function(){immersiveLift();openCardScreen()};
const immersiveBall=ballSession;ballSession=function(){immersiveBall();openCardScreen()};
const immersiveDaily=beginDaily;beginDaily=function(){immersiveDaily();if(document.body.classList.contains('lesson-mode'))openCardScreen()};
const immersiveComplete=cardComplete;cardComplete=function(){immersiveComplete();openCardScreen()};
const immersiveHub=showHub;showHub=function(page='Today'){document.body.classList.remove('fullscreen-card');immersiveHub(page)};
let boardActor='A',boardAction='move',boardModel=null,boardPoint=null,boardMessage='';
function resetBoard(){boardModel={actors:{A:[65,180],B:[180,120],D:[205,75]},frames:[{text:'Start here.',ball:[75,170]}]};boardActor='A';boardAction='move';boardPoint=null;boardMessage=''}
function boardState(){const actors=JSON.parse(JSON.stringify(boardModel.actors));let owner='A',ball=boardModel.frames[0].ball;for(const f of boardModel.frames){Object.assign(actors,f.actors||{});if(f.owner)owner=f.owner;if(f.ball)ball=f.ball}return {actors,owner,ball}}
function addBoardMove(){if(!boardPoint)return;const state=boardState();if(boardModel.frames.length>=9){boardMessage='Play is full. Undo a move to change it.';return}if(boardAction==='move'){const old=state.actors[boardActor],dest=boardPoint;boardModel.frames.push({text:boardActor+' moves into space.',actors:{[boardActor]:dest},run:[old,dest],ball:state.owner===boardActor?[dest[0]+8,dest[1]-8]:state.ball})}else{const target=Object.keys(state.actors).filter(id=>id!==state.owner).sort((a,b)=>Math.hypot(state.actors[a][0]-boardPoint[0],state.actors[a][1]-boardPoint[1])-Math.hypot(state.actors[b][0]-boardPoint[0],state.actors[b][1]-boardPoint[1]))[0];if(Math.hypot(state.actors[target][0]-boardPoint[0],state.actors[target][1]-boardPoint[1])>35){boardMessage='Tap the player who should receive.';return}const dest=[state.actors[target][0]+8,state.actors[target][1]-8];boardModel.frames.push({text:state.owner+' passes to '+target+'.',pass:[state.ball,dest],ball:dest,owner:target})}boardPoint=null;boardMessage='Move added. Add another or play it back.'}
function renderBoard(){document.body.classList.add('lesson-mode');const last=boardModel.frames.length-1;hub.innerHTML=`<article class="visual-builder"><p class="quiet-label">YOUR PLAY</p><h1>Move the pieces.</h1><div class="board-tools"><div>${['A','B','D'].map(id=>`<button data-board-actor="${id}" aria-pressed="${id===boardActor}">${id}</button>`).join('')}</div><div><button data-board-action="move" aria-pressed="${boardAction==='move'}">↗ Move</button><button data-board-action="pass" aria-pressed="${boardAction==='pass'}">⚽ Pass</button></div></div><div class="tap-board" id="tapBoard">${playSvg(boardModel,last)}</div><p class="builder-cue">${boardAction==='move'?'Tap where '+boardActor+' should go.':'Tap the receiving player.'}</p><p class="builder-status" role="status">${escapeHTML(boardMessage)}</p><div class="row"><button data-board-undo ${last===0?'disabled':''}>↶ Undo</button><button data-board-reset>↻ Reset</button><button class="primary" data-board-preview ${last===0?'disabled':''}>▶ Play ${last} moves</button></div><details><summary>What the pieces mean</summary><p>A and B are teammates. D is an opponent. Pass starts from whoever has the ball. This is a drawing tool, not a coach checking whether a move is right.</p></details></article>`;openCardScreen();$('tapBoard').onclick=e=>{const rect=e.currentTarget.getBoundingClientRect();boardPoint=[Math.max(30,Math.min(270,(e.clientX-rect.left)*300/rect.width)),Math.max(35,Math.min(205,(e.clientY-rect.top)*240/rect.height))];addBoardMove();renderBoard()}}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.closeCard!==undefined){clearSessionClock();showHub('Today')}if(d.openBoard!==undefined){resetBoard();renderBoard()}if(d.boardActor){boardActor=d.boardActor;renderBoard()}if(d.boardAction){boardAction=d.boardAction;boardMessage='';renderBoard()}if(d.boardUndo!==undefined){if(boardModel.frames.length>1)boardModel.frames.pop();renderBoard()}if(d.boardReset!==undefined){resetBoard();renderBoard()}if(d.boardPreview!==undefined){customPlay=JSON.parse(JSON.stringify(boardModel));playFocus=prefs().focus;playBeat=0;step=0;focusStep()} });
let exitTouch=null;
document.addEventListener('touchstart',e=>{exitTouch=document.body.classList.contains('fullscreen-card')&&hub.scrollTop===0&&!e.target.closest('button,input,textarea,select,.tap-board')?{x:e.touches[0].clientX,y:e.touches[0].clientY}:null},{passive:true});
document.addEventListener('touchend',e=>{if(!exitTouch)return;const dx=e.changedTouches[0].clientX-exitTouch.x,dy=e.changedTouches[0].clientY-exitTouch.y;exitTouch=null;if(dy>110&&dy>Math.abs(dx)*1.5){clearSessionClock();showHub('Today')}},{passive:true});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.body.classList.contains('fullscreen-card')){clearSessionClock();showHub('Today')}});
showHub('Today');
const immersiveLog=logForm;logForm=function(kind){const full=document.body.classList.contains('fullscreen-card');immersiveLog(kind);if(full)openCardScreen()};
